# region: sift
def sift(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: intake
def intake(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs, factor=3):
    return [v * factor for v in xs]

# region: digest
def digest(xs):
    n = len(xs)
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': min(xs) if xs else 0}

# region: emit
def emit(summary):
    out = dict(summary)
    out['flags'] = sorted(k for k, v in summary.items() if isinstance(v, int) and v > 0)
    return out

# region: run
def run(raw):
    return emit(digest(fold(intake(sift(raw)))))

